import{z as B,x as E,o as i,c,q as s,j as r,D as d,d as a,s as n,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"模式位","description":"","frontmatter":{"title":"模式位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/file-mode-bits.md","filePath":"cs/file-mode-bits.md","lastUpdated":1791063341000}'),p={name:"cs/file-mode-bits.md"};function m(A,e,h,u,x,f){const t=E("Mermaid");return i(),c("div",null,[e[2]||(e[2]=s('<h1 id="模式位" tabindex="-1">模式位 <a class="header-anchor" href="#模式位" aria-label="Permalink to &quot;模式位&quot;">​</a></h1><div class="epigraph"><p>每个 inode 带有类型与 rwx 三位一组：属主、同组、其他人；内核在 open 与执行时按有效身份核对。</p><footer>—— 据 Ritchie and Thompson；Bach；POSIX 对 mode 的整理</footer></div><p><a href="/cs/crash-consistency">上一课</a>保证恢复后 inode 还在。<a href="/cs/inode-dir">inode 与目录</a> 已列权限字段，尚未当课。<a href="/cs/path-lookup">路径查找</a> 用了目录搜索位。缺口是把 <strong>st_mode</strong> 收成可执行的规则：类型比特、九位 rwx、以及与后课 setuid 的接口。不是 ACL 百科——那是安全课更细的模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只有「能 open 就能读写」，多用户机器无法共享 <code>/tmp</code> 又保住私有文件。Unix：uid/gid 对 inode 的 uid/gid，匹配属主则看属主三位，否则看组，再否则看 other。目录的 r=读目录项，w=增删项，x=把该目录当查找路径。文件的 x=允许 exec。缺口不是新的磁盘块，而是 <code>open</code>/<code>execve</code> 里的这次比较。</p><p>本课不把 POSIX ACL 的每一项写成默认。</p><p><span class="marginnote"><code>umask</code> 在创建时关掉一些位。<code>chmod</code> 改模式。类型（普通、目录、链接、设备）占 mode 的高位，与 rwx 共存一个字。</span></p>',7)),(i(),r(l,null,{default:d(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22mode%200o750%20%3D%20rwxr-x---%22%5D%20--%3E%20T%5B%22%E9%AB%98%E4%BD%8D%E7%B1%BB%E5%9E%8B%3A%20%E6%99%AE%E9%80%9A%E6%96%87%E4%BB%B6%22%5D%0A%20%20M%20--%3E%20O%5B%22%E5%B1%9E%E4%B8%BB%20rwx%20%3D%20111%3A%20%E8%AF%BB%2B%E5%86%99%2B%E6%89%A7%E8%A1%8C%22%5D%0A%20%20M%20--%3E%20G%5B%22%E7%BB%84%20r-x%20%3D%20101%3A%20%E8%AF%BB%2B%E6%89%A7%E8%A1%8C%2C%20%E4%B8%8D%E5%8F%AF%E5%86%99%22%5D%0A%20%20M%20--%3E%20X%5B%22%E5%85%B6%E4%BB%96%20---%20%3D%20000%3A%20%E4%B8%80%E5%BE%8B%E6%8B%92%E7%BB%9D%22%5D%0A%20%20O%20--%3E%20C%5B%22%E5%86%85%E6%A0%B8%E6%8C%89%E8%BA%AB%E4%BB%BD%E6%8C%91%E4%B8%80%E7%BB%84%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20G%20--%3E%20C%0A%20%20X%20--%3E%20C%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("p",null,[o("span",{class:"marginnote"},[a("数字实例："),o("code",null,"chmod 750 f"),a(" 里的 750 是八进制：7 = 二进制 111（rwx），5 = 101（r-x），0 = ---。合起来就是「属主全能、同组可读可进入、其他人一律拒绝」。每三位一组正好对应一位八进制数。")])],-1)),e[4]||(e[4]=o("h2",{id:"方法",tabindex:"-1"},[a("方法 "),o("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),e[5]||(e[5]=o("p",null,[a("创建：申请 inode，写入创建者 uid/gid 与 "),o("code",null,"mode & ~umask"),a("。访问：沿路径已查过各目录 x；对目标比较 r/w。root（或有能力者）通常绕过，除执行位等少数例外——细节留给安全课。与 "),o("a",{href:"/cs/vfs"},"VFS"),a(" 接头：具体 FS 把 mode 存在 inode，VFS 做通用检查。")],-1)),(i(),r(l,null,{default:d(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E6%9C%89%E6%95%88%20uid%2Fgid%22%5D%20--%3E%20MATCH%7B%22%E5%B1%9E%E4%B8%BB%2F%E7%BB%84%2F%E5%85%B6%E4%BB%96%22%7D%0A%20%20MATCH%20--%3E%20RWX%5B%22%E5%AF%B9%E5%BA%94%E4%B8%89%E4%BD%8D%22%5D%0A%20%20RWX%20--%3E%20DEC%5B%22%E5%85%81%E8%AE%B8%E6%88%96%20EACCES%22%5D%0A"})]),fallback:d(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模式位把隔离从页表接到文件对象：同一内核，不同用户看见不同可打开集合。它不代替用户/内核分裂。管道与套接字也有 inode 模式，但常由创建者限定。不要把模式位写成提权 cookbook；只讲核对发生在 VFS。</p><p>下一课的 setuid 会在 exec 时暂时改有效 uid，本课的比较规则仍然适用，只是「有效身份」变了。</p><p><span class="marginnote">直觉类比：目录的 x 位像走廊的门禁——没有 x，你连走进去翻目录项（按名字找文件）的资格都没有；r 只是让你站在门口抄目录名单。所以「能列出目录内容」不等于「能打开里面的文件」，后者还要看文件自身的九位。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SELinux 标签。不把 Windows ACL 当对照考试。粘滞位、setgid 目录继承在下一课与 setuid 一起，以免本课吞并。安全栏的最小特权会引用本课九位，不在这里重写。</p><p>后课默认：open/exec 按九位核对。exec 时身份提升与 <code>/tmp</code> 删除规则，下一课 setuid 与粘滞位。</p><p><span class="marginnote">常见误区：初学者遇到「打不开文件」就 <code>chmod 777</code>。正确做法是先问「我是谁（id）」「文件归谁（ls -l）」，再看该走属主、组还是其他那一组；滥开 777 会把写权限暴露给机器上所有用户，root 绕过检查也是少数例外而非常规。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mode 含类型与三组 rwx；目录 x 是搜索。</li><li>核对用有效 uid/gid；umask 限制新建。</li><li>setuid/粘滞位是下一课。</li><li>出处：Ritchie and Thompson, 1974；Bach, <em>UNIX</em>；POSIX <code>&lt;sys/stat.h&gt;</code>。</li></ul>',10))])}const C=B(p,[["render",m]]);export{_ as __pageData,C as default};
